refentry.refsect1:
&reftitle.description;
boolarray_all arrayarray callablecallback
array_all restituisce &true; se la callback fornita restituisce &true; per tutti gli elementi. In caso contrario la funzione restituisce &false;.

&reftitle.returnvalues;

 La funzione restituisce &true; se callback restituisce
 &true; per tutti gli elementi. In caso contrario la funzione restituisce &false;.

  &reftitle.examples;

   Esempio di array_all


<?php
$array = [
    'a' => 'dog',
    'b' => 'cat',
    'c' => 'cow',
    'd' => 'duck',
    'e' => 'goose',
    'f' => 'elephant'
];

// Verifica se tutti i nomi di animali sono più corti di 12 lettere.
var_dump(array_all($array, function (string $value) {
    return strlen($value) < 12;
}));

// Verifica se tutti i nomi di animali sono più lunghi di 5 lettere.
var_dump(array_all($array, function (string $value) {
    return strlen($value) > 5;
}));

// Verifica se tutte le chiavi dell'array sono stringhe.
var_dump(array_all($array, function (string $value, $key) {
   return is_string($key);
}));
?>


   &example.outputs;


bool(true)
bool(false)
bool(true)
